    {
      "path": "src/tools/table.ts",
      "content": "// 「模型工具表」开关。\n//\n// 为什么要有它：工具表是按**每个请求**付钱的 —— 每一轮都随请求发出工具 schema，哪怕这一轮\n// 根本用不上。关掉某几个工具，它们整份不进请求（不是\"把描述写短点\"那种省）；面板\n// （118 个 op）与注入通道完全不受影响。\n//\n// 出厂**默认就关着十八条**（整张表 24 条，每轮实发 6 条）—— 名单、判据与代价见下面\n// `DEFAULT_HIDDEN_TOOLS`；用户自己额外关的与出厂关的在合计那句里分开报。\n//\n// 实测数字（口径：宿主 `recordToolSize` 的 `ceil(JSON.stringify(header.tools).length / 4) + 4`，\n// 即**字符数 / 4**；`header.tools` 里只有 name / description / parameters —— 官方的\n// `projectToolSchema` 不投影 output / execute，那几个不进请求。界面「模型工具表」那行\n// 合计与逐条 ≈tok 就是这份）：\n//   · 十八条隐藏 ≈**4,524 tok**，默认可见那六条 ≈**1,536 tok**，全开 ≈**6,055 tok**。\n//   · A/B 实测（同一次请求里把十九条逐个打开，前后各跑两轮）净少 **4,119 / 4,197 tok**，\n//     对照当天那份合计 4,186 略低是正常的（边界按 ceil 逐个算、四条一合并就省下那几个 +4），\n//     所以它们是**净节省的下界**，不是\"省了多少\"的上界。**那对数量的是当天那份描述** ——\n//     描述一改就得重测，新的净省要在真实环境跑 A/B，这里不拿估算冒充实测。\n//\n// ⚠️ **那个口径不是 token 数，别拿它跟别的数直接比**（用真 BPE 词表实测）：\n// 工具描述是英文，`字符数 / 4` 对英文**高估约 10%** —— 18 个工具那一版真实是 ≈3,137 tok（o200k）。\n// 反方向也一样：注入段是中文，同一个口径对它**低估约 13%**（四段 716 → 真 823）。\n// 所以\"工具表 / 注入\"这两个数不是同一把尺子，跨语言比大小会得出错的结论。\n// 口径本身是**宿主的**（`recordToolSize`），我们改不了；能做的只是知道它偏在哪。\n//\n// 当前环境**没有 BPE 分词器可实测**：官方包里零个词表文件，本机也没有 tiktoken /\n// transformers。所以上面那些只是**按宿主的尺子**量出来的数，真 BPE 值按上面那条经验约低一成 ——\n// 没有实测，别当实测引用。\n//\n// 本文件只放纯逻辑（normalize / 分域分组 / 体积汇总）。落盘与 TTL 缓存在 index.ts，与\n// 注入设置（`inject-settings.json`）走同一套写法。\n//\n// 谁读这份设置：\n//   · index.ts 的 op `tool-table`（读写侧车 + 写后刷新可见性与两个目录）——\n//     带 `sessionId` 的那一支改的是**本对话**的整份名单（存 `scope-overrides.json`），\n//     这份侧车只剩\"新对话的默认模板\"与方案库；\n//   · mcp/manager.ts 的 `pluginHiddenTools` —— 官方 `tools.restrict()` 只允许**每个 agent\n//     scope 一层**限制（两处各调一次会互相覆盖），所以 MCP 停用名单与我们的名单必须在那边\n//     并成一次 restrict；\n//   · 工具执行门禁（关掉的工具即便被点到也不执行 —— 可见性半边失败时仍有这一半）；\n//   · 注入通道与两个目录：目录里「用 `skill_manager_list` 查」这类句子在工具关掉后就是假的。\n\nimport { INJECT_DOMAIN_KEYS, domainOfTool, type InjectDomainKey } from '../context-inject.js'\nimport { LEGACY_TOOL_NAME_MAP } from '../legacy-tool-names.js'\nimport { CONTROL_TOOL_NAME } from './deps.js'\n\n/** 一份命名方案：名字 + 那一组\"不发给模型\"的工具名（与 `hidden` 同口径，不是\"开着哪些\"）。 */\nexport interface ToolTablePreset {\n  name: string\n  hidden: string[]\n}\n\n/**\n * 侧车 `tool-table.json` 的形状。\n *\n * `hidden` 是**当前生效**的那份；`presets` 是用户存下来的命名方案（界面「保存方案 / 恢复方案」）。\n * 两者同处一份文件是刻意的：方案只是\"另一份 hidden\"，分开存就要处理两份真相互相落后\n * （改完当前忘了同步方案，或反过来）。\n */\nexport interface ToolTableSettings {\n  hidden: string[]\n  presets: ToolTablePreset[]\n}\n\n/**\n * 出厂默认关掉的**十七条**：整张表 24 条，关掉后**每轮实发 7 条**。\n *\n * 判据只有一条：**这些信息或动作常态下由注入段与面板承担，\n * 平时也用不到模型自己伸手**。分五组：\n *   · **写侧五条** —— 三个 `*_save`（MCP / 技能 / 人设：配置本体在面板上改）+\n *     `prompt_manager_apply`（当前生效的那份本来就在 `Current prompt` 注入段里）+\n *     `plugin_manager_remove`（删除进回收站可恢复，但常态下由面板承担）。\n *   · **读侧六条** —— `mcp_manager_list` / `skill_manager_list` / `prompt_manager_list` /\n *     `scene_manager_list` 四个清单 + `memory_manager_read` + `memory_manager_search`。\n *     会话开头注入的那几段目录已经写了当前有什么，模型不必每轮再带一份查询工具。\n *   · **切场一条** —— `scene_manager_switch`：进入 / 退出场景。\n *   · **开关三条** —— `skill` / `memory` / `subagent` 三个 `_switch`（用户：「平时使用也很少」）。\n *     启停在面板上都有同款，注入段也写着当前开着哪些。**`mcp_manager_switch` 刻意留着**：\n *     它是\"这台先给我关了\"这条最常用的临时动作的唯一入口，也是 MCP 域留下来的一条腿。\n *   · **建档两条** —— `scene_manager_save`（场景记录）+ `scene_manager_archive`（档案段：\n *     进入时开哪些 MCP / 技能 / 人设）。配置本体在面板上改；档案的勾选集机器自己算得出来\n *     （`capture`），模型逐项填反而容易填错。\n *\n * 人设域**没有官方载体兜底**：MCP / 技能 / 记忆三个域即便目录被压制型预设压掉，也各自还留着\n * 一条常驻发现路径（各自的 list 工具），而人设目录一旦不注入，模型手里就只剩\n * `subagent_manager_run` —— 人设的 id 就是名字，`run` 报错时会把当前可委派的那几个列出来，\n * 但那要先猜错一次。这条清单工具（≈165 tok/轮）**默认关**：常态下人设目录已经在注入段里，\n * 它只是那份的**全量版**（停用的、场景外的、每个人设正文在哪），要全量清单时模型自己就能\n * 打开它（控制面工具那条永远在）。\n *\n * 技能 / 人设\"是常问的，但它**低频于\"读现状 + 拨开关 + 建改定义\"**那批，而且面板每个域都有\n * 删除入口 —— 默认关、要用时在「兼容」页勾上（与另外十七条同一条纪律，不额外付 token）。\n *\n * 关掉的这些**模型自己也能打开**：`tool_manager_tools`（每轮常驻的那一条）能按对话\n * 打开任意一条被关掉的工具，列清单时给出名字、一句话用途与 ≈token。这条工具不在\n * 这份名单里 —— 它是唯一的回头路，自己关掉自己的话就再也开不回来了。\n *\n * ⚠️ 关掉的是**能力**，不是\"冗余\"，代价如实记在这里（要拿回来就在「兼容」页勾，或整批换：\n * 「恢复方案」）：注入的目录是**筛过的视图**（MCP 段只列可用/曾可用的、人设目录只列本场景\n * 绑定且深度够的、技能目录只列可调用的），所以\"没开的那几台 / 被同名覆盖的那份技能 / 没进\n * 上下文的记忆正文\"在会话里查不到；`*_switch` 关掉后模型也不能再替你拨启停。三处配套改动为\n * 的就是不把模型往墙上推：目录被条数上限截断时那句「用 `X_manager_list` 查」自动退回「另有\n * N more not listed.)」（`listToolVisible`）；`mcp_manager_list` / `skill_manager_read` 里\"没找到 →\n * 去调 list\"那两句先问 `deps.toolVisible`；`memory_manager_list` 的描述不再点名已关的工具。\n *\n * 只在**用户从没记过选择**时生效（见 index.ts 的 `toolTableSettingsFrom`：侧车文件读不出来\n * 才用这份）。已经存过盘的一律照原样，包括显式的 `hidden: []` —— 那是\"我全都要\"，\n * 不是\"还没配过\"。存过盘的人要拿回这份默认，走界面上的「恢复方案 → 出厂默认」。\n */\nexport const DEFAULT_HIDDEN_TOOLS: readonly string[] = Object.freeze([\n  'scene_manager_list',\n  'scene_manager_switch',\n  'scene_manager_save',\n  'scene_manager_archive',\n  'memory_manager_read',\n  'memory_manager_search',\n  'memory_manager_switch',\n  'mcp_manager_list',\n  'mcp_manager_save',\n  'skill_manager_list',\n  'skill_manager_switch',\n  'skill_manager_save',\n  'subagent_manager_list',\n  'subagent_manager_switch',\n  'subagent_manager_save',\n  'prompt_manager_list',\n  'prompt_manager_apply',\n  'plugin_manager_remove',\n])\n\n/** 出厂默认那份设置：十八条不发（名单与理由见上面），方案清单是空的。 */\nexport const DEFAULT_TOOL_TABLE_SETTINGS: ToolTableSettings = { hidden: [...DEFAULT_HIDDEN_TOOLS], presets: [] }\n\n/** 方案名上限（与 MCP 备注那类输入同风格：短到能在一行里读，长了也没人看）。 */\nexport const PRESET_NAME_MAX_LENGTH = 40\n/**\n * 场景档案绑定「出厂默认那份」时用的方案名。\n * 它不是一个可保存的方案名，只在档案里当哨兵用；解析时用户存的同名方案优先。\n */\nexport const FACTORY_TOOL_TABLE_PRESET = 'factory-default'\n/** 存得下的方案数上限 —— 侧车是人手能审的文件，不放开。 */\nexport const PRESET_MAX_COUNT = 20\n\nconst DEFAULT_HIDDEN_SET: ReadonlySet<string> = new Set(DEFAULT_HIDDEN_TOOLS)\n\n/** 夹一份工具名名单（只收非空字符串；重复的只留一份）。 */\nfunction normalizeNameList(list: unknown): string[] {\n  const out: string[] = []\n  if (!Array.isArray(list)) return out\n  for (const item of list) {\n    // 只认字符串：`[7]` 这种手改产物不该被 String() 变成一个看着像工具名的东西。\n    if (typeof item !== 'string') continue\n    const name = item.trim()\n    if (name !== '' && out.indexOf(name) < 0) out.push(name)\n  }\n  return out\n}\n\n/** 夹一份方案清单：名字非空且截到上限、同名只留第一个、总数封顶（超出的是手改产物，丢掉不如不认）。 */\nfunction normalizePresetList(list: unknown): ToolTablePreset[] {\n  const out: ToolTablePreset[] = []\n  if (!Array.isArray(list)) return out\n  for (const item of list) {\n    if (!item || typeof item !== 'object') continue\n    const raw = item as Record<string, unknown>\n    if (typeof raw.name !== 'string') continue\n    const name = raw.name.trim().slice(0, PRESET_NAME_MAX_LENGTH)\n    if (name === '' || !Array.isArray(raw.hidden)) continue\n    if (out.some((p) => p.name === name)) continue\n    out.push({ name, hidden: normalizeNameList(raw.hidden) })\n    if (out.length >= PRESET_MAX_COUNT) break\n  }\n  return out\n}\n\n/** 把任意输入夹成合法设置（缺字段 / 类型不对的条目一律不认，绝不凭空造方案）。 */\nexport function normalizeToolTableSettings(raw: unknown): ToolTableSettings {\n  const obj = (raw && typeof raw === 'object' ? raw : {}) as Record<string, unknown>\n  return { hidden: normalizeNameList(obj.hidden), presets: normalizePresetList(obj.presets) }\n}\n\n/**\n * 读侧入口：**从没记过选择**（侧车不存在 / 读不出，`readJsonFile` 给 `null`）时给出厂默认，\n * 其余一律按盘上那份夹一遍。\n *\n * 为什么必须分这一叉：默认值不能合成在 `normalize` 里，否则用户把五条全打开、存下\n * `hidden: []` 之后，下一次读又会把它们关回去 —— 那是把\"我全都要\"读成\"还没配过\"。\n */\nexport function toolTableSettingsFrom(raw: unknown): ToolTableSettings {\n  return raw === null || raw === undefined ? DEFAULT_TOOL_TABLE_SETTINGS : normalizeToolTableSettings(raw)\n}\n\n/**\n * 严格结构检查：宽松归一化会把「合法 JSON 但形状错了」读成 `hidden: []`\n * ——也就是**全部打开**，用户关掉的工具会在执行守卫眼皮底下复活。\n *\n * 只把真正影响可见性的字段判为损坏：顶层必须是对象、`hidden` 必须是字符串数组、\n * `presets` 必须是数组。方案条目的残缺仍按原口径跳过 —— 它不改变当前 hidden，\n * 不该因为一条手工改坏的方案把整份设置锁死。\n */\nexport function classifyToolTableSettings(raw: unknown): { ok: true; value: ToolTableSettings } | { ok: false; error: string } {\n  if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) return { ok: false, error: '顶层必须是对象' }\n  const obj = raw as Record<string, unknown>\n  if (obj.hidden !== undefined) {\n    if (!Array.isArray(obj.hidden)) return { ok: false, error: 'hidden 必须是字符串数组' }\n    for (const item of obj.hidden) {\n      if (typeof item !== 'string') return { ok: false, error: 'hidden 里出现了非字符串条目' }\n    }\n  }\n  if (obj.presets !== undefined && !Array.isArray(obj.presets)) return { ok: false, error: 'presets 必须是数组' }\n  return { ok: true, value: normalizeToolTableSettings(raw) }\n}\n\n/**\n * 旧工具名 → 新工具名迁移表（几轮改名累积）。\n *\n * 为什么必须有它：`tool-table.json` 存的是**用户点名关掉的那些工具**。几族并成 17 条\n * 之后，旧名在新表里根本不存在 —— 不迁移的话，用户\"关掉了某条\"的意图会在新名字上**静默失效**\n * （那条工具照旧每轮发出去，而他以为早就关了）。\n *\n * 映射规则不是字符串替换而是**语义合并**：两条旧工具并成一条 `save` 时，只要原来关掉了其中\n * 任意一条，就应当关掉新的那条 —— 用户当时的意图是\"别让模型碰这件事\"。\n *\n * 只翻译**认识的名字**，其余原样保留：我们无法区分\"用户的旧名\"与\"别的插件的工具名\"，\n * 误删别人的条目比留着一条死名更糟。\n *\n * 表本身放在根目录那一叶（`src/legacy-tool-names.ts`）：它还有两个使用方在更低的层\n * （会话侧车、场景快照），那些层不能反向引本文件。\n */\nexport { LEGACY_TOOL_NAME_MAP } from '../legacy-tool-names.js'\n\n/**\n * 把一份设置里的旧工具名翻译成新名（**幂等**：已经全是新名时 `changed` 为 false、原样返回）。\n * 翻译后按新名去重（两条旧名并成同一条 save 时只留一份）。\n *\n * 命名方案**一起翻译**：方案里存的就是工具名，只翻当前那份的话，用户恢复旧方案时会把\n * 已经改名的条目原样铺回当前设置 —— 那条\"静默失效\"的毛病只是晚一步发生。\n */\nexport function migrateLegacyToolNames(settings: ToolTableSettings): { settings: ToolTableSettings; changed: boolean } {\n  let changed = false\n  const translate = (list: readonly string[]): string[] => {\n    const out: string[] = []\n    for (const raw of list) {\n      const name = LEGACY_TOOL_NAME_MAP[raw] ?? raw\n      if (name !== raw) changed = true\n      if (out.indexOf(name) < 0) out.push(name)\n    }\n    return out\n  }\n  const hidden = translate(settings.hidden)\n  const presets = settings.presets.map((p) => {\n    const next = translate(p.hidden)\n    // 逐字比对，不能只比长度：`skill_manager_create → skill_manager_save` 是**一对一**，\n    // 长度不变 —— 拿长度当\"有没有变\"的判据会把翻译结果整份丢掉（方案里留的还是旧名）。\n    const same = next.length === p.hidden.length && next.every((n, i) => n === p.hidden[i])\n    return same ? p : { name: p.name, hidden: next }\n  })\n  return changed ? { settings: { hidden, presets }, changed: true } : { settings, changed: false }\n}\n\n/**\n * 新存一份命名方案：**同名不覆盖**（用户 ：「保存方案不能同名」）。\"保存\"这颗按钮\n * 不该悄悄改掉一份已有的记录 —— 那是破坏性动作，而它连一句确认都没有。撞名时 `exists=true`\n * 且原样返回，由调用方在写盘之前挡下来并如实报错。封顶同样由调用方挡（超了要报错，不是静默丢）。\n */\nexport function addPreset(settings: ToolTableSettings, name: string, hidden: readonly string[]): { settings: ToolTableSettings; exists: boolean } {\n  if (settings.presets.some((p) => p.name === name)) return { settings, exists: true }\n  return {\n    settings: { hidden: settings.hidden, presets: settings.presets.concat([{ name, hidden: normalizeNameList(hidden) }]) },\n    exists: false,\n  }\n}\n\n/** 删一份方案。名字不认识时 `changed=false` —— 由调用方如实报，不静默成功。 */\nexport function dropPreset(settings: ToolTableSettings, name: string): { settings: ToolTableSettings; changed: boolean } {\n  const presets = settings.presets.filter((p) => p.name !== name)\n  if (presets.length === settings.presets.length) return { settings, changed: false }\n  return { settings: { hidden: settings.hidden, presets }, changed: true }\n}\n\n/** 注册时量到的工具体积（`JSON.stringify(definition).length`，见 index.ts 的 register 包装）。 */\nexport interface ToolTableRow {\n  name: string\n  bytes: number\n}\n\n/** 工具表里的一条工具：全名、所属族与是否可关。 */\nexport interface ToolTableTool {\n  name: string\n  tok: number\n  hidden: boolean\n  /** 这条在出厂默认名单里（合计那句\"其中 ≈X 是出厂默认关掉的\"、悬停与「恢复方案」都取它）。 */\n  defaultHidden: boolean\n}\n\n/** 工具表里的一个族：族名、显示名与成员。 */\nexport interface ToolTableGroup {\n  /** 域 key；与注入域清单（context-inject 的 INJECT_DOMAIN_KEYS）同源。认不出前缀的工具归到 `other`。 */\n  key: InjectDomainKey | 'control' | 'other'\n  tools: ToolTableTool[]\n  /** 该域全部工具的 ≈token 合计（含关掉的）。 */\n  tok: number\n  /** 其中当前关掉的 ≈token 合计。 */\n  hiddenTok: number\n}\n\n/** 工具表报告：分组、关停名单与「关掉会失去什么」的提示。 */\nexport interface ToolTableReport {\n  groups: ToolTableGroup[]\n  /** 当前会随请求发出的部分。 */\n  visibleTok: number\n  /** 当前不发的那部分（关对了就是这个数）。**不含**载体让位那一档。 */\n  hiddenTok: number\n  totalTok: number\n  visibleCount: number\n  hiddenCount: number\n  totalCount: number\n  /**\n   * 当前关掉的里面有几条是**出厂就关**的（用户没动过它们）。\n   *\n   * 给「功能总览」用：`hiddenCount - defaultHiddenCount` 才是\"用户自己关掉的条数\"。\n   * 把出厂默认报成异常，等于把插件自己的选择读成用户的故障 —— 与兼容页那条\n   * 「琥珀只留给'该投却没投'」的口径冲突。\n   */\n  defaultHiddenCount: number\n  /** 那几条当前省下的 ≈token。 */\n  defaultHiddenTok: number\n  /**\n   * 「有官方等价物 ⇒ 我们让位」而当前**不发**的那部分（`skill_manager_read`）。\n   *\n   * 为什么单开一档，不并进 `hiddenTok`：那一档的语义是\"用户或出厂关掉的\"，界面用\n   * `hiddenCount - defaultHiddenCount` 反推\"用户自己关了几条\"。载体让位既不是用户关的、\n   * 也不是出厂关的 —— 并进去，兼容页就会报出一个假的\"用户关掉了 1 条\"。\n   * 而**不计入可见**是必须的：那条工具在标准预设下确实不进请求（`index.ts` 的\n   * `CARRIER_DUPLICATES`），报成\"实发\"就是虚报。\n   */\n  carrierHiddenCount: number\n  carrierHiddenTok: number\n}\n\n/**\n * 宿主与界面共用的字符/词比（`dsh-token-meter` 的 `CHARS_PER_TOKEN`，其\n * `estimateToolsTokens` = `ceil(JSON.stringify(tools).length / 4) + 4`）。\n *\n * 这是**估算**：宿主自己也这么说（\"Actual usage remains authoritative\"，真实用量来自\n * API 的 `stream_options.include_usage`）。界面上必须带「≈」。\n */\nexport const CHARS_PER_TOKEN = 4\n\n/** 按宿主的尺子把字节数估成 token 数（经验值，见文件头；不是 BPE 实测）。 */\nexport function estimateTok(bytes: number): number {\n  const value = Number(bytes)\n  if (!Number.isFinite(value) || value <= 0) return 0\n  return Math.ceil(value / CHARS_PER_TOKEN)\n}\n\n/**\n * 一句话用途的字符上限（模型看「这条工具能干什么」时用）。\n *\n * 为什么截：整段描述在模型读 schema 时已经在上下文里，重复贴一遍只是把回执撑大；\n * 清单是**按需**调用，一次贴二十条整段描述就是几千字符。\n */\nexport const TOOL_SUMMARY_MAX = 180\n\n/**\n * 从工具描述里取一句话用途：第一行非空行，截到 {@link TOOL_SUMMARY_MAX}。\n *\n * 各工具描述的组织惯例是「是什么 → 怎么做 → 何时用」，首句就是「是什么」。\n * 空描述返回空串（那一条在清单里就只留名字）。\n */\nexport function summarizeToolDescription(description: unknown): string {\n  const text = String(description ?? '')\n  const line = text.split('\\n').find((l) => l.trim() !== '') ?? ''\n  const trimmed = line.trim()\n  return trimmed.length > TOOL_SUMMARY_MAX ? trimmed.slice(0, TOOL_SUMMARY_MAX - 1) + '…' : trimmed\n}\n\n/**\n * 逐条改一份关停名单：返回新的名单（不改动入参）。\n *\n * 为什么要有「改一格」而不只有「整份替换」：整份替换要先**读出**当前名单再算差量，\n * 而那次读与后面那次写之间有窗口 —— 两个写者（面板、模型）各拿一份旧名单写回时，\n * 后写的会把先写的覆盖掉（丢更新）。逐条改可以在写锁里现读现改，窗口消失。\n *\n * `hidden: true` = 关掉（进名单），`false` = 打开（出名单）。\n */\nexport function applyToolTableToggles(\n  current: readonly string[],\n  toggles: ReadonlyArray<{ name: string; hidden: boolean }>,\n): string[] {\n  const out = current.slice()\n  for (const t of toggles) {\n    const i = out.indexOf(t.name)\n    if (t.hidden) { if (i < 0) out.push(t.name) } else if (i >= 0) out.splice(i, 1)\n  }\n  return out\n}\n\n/**\n * 纯函数：把注册时量到的体积按域分组，标出哪些被关掉，给出四档合计。\n *\n * 顺序：域按 `INJECT_DOMAIN_KEYS`（界面与注入通道同一顺序），域内按**注册顺序**\n * —— 改顺序等于改显示顺序，不额外定义\"重要性\"，免得出现第二份排序真相。\n *\n * `carrierHidden` 是\"官方载体在场时我们主动让位\"的名字（当前只有 `skill_manager_read`）。\n * 它是 **per-agent** 的（取决于那个 agent 的 scope 解析得到解析不到官方 `skill`），而报表是\n * 全局的 —— 所以由调用方给一份口径明确的名单（`tool-table-switch.ts` 传的是\"标准预设下会\n * 让位\"的保守估计），本函数只负责把它从**可见**里扣掉、单独计一档。\n */\nexport function buildToolTableReport(\n  rows: readonly ToolTableRow[],\n  hidden: readonly string[],\n  carrierHidden: readonly string[] = [],\n): ToolTableReport {\n  const off = new Set(hidden.map((name) => String(name)))\n  const carried = new Set(carrierHidden.map((name) => String(name)))\n  // 「控制」组排在最前：它是**管着这张表的那一条工具**，放在末尾的「其它」组里\n  // 等于把它放到离它要控制的东西最远的地方。\n  const buckets = new Map<InjectDomainKey | 'control' | 'other', ToolTableTool[]>()\n  buckets.set('control', [])\n  for (const key of INJECT_DOMAIN_KEYS) buckets.set(key, [])\n  for (const row of rows) {\n    const name = String(row && row.name ? row.name : '').trim()\n    if (name === '') continue\n    // 认不出前缀的工具归到 `other` 而不是丢掉：丢掉 = 它在界面上根本不出现，\n    // 于是\"没登记的域\"就永远关不掉，而且没人看得出来（静默降级）。\n    const key = name === CONTROL_TOOL_NAME ? 'control' : (domainOfTool(name) ?? 'other')\n    let list = buckets.get(key)\n    if (list === undefined) { list = []; buckets.set(key, list) }\n    list.push({ name, tok: estimateTok(row.bytes), hidden: off.has(name), defaultHidden: DEFAULT_HIDDEN_SET.has(name) })\n  }\n  const groups: ToolTableGroup[] = []\n  let visibleTok = 0\n  let hiddenTok = 0\n  let visibleCount = 0\n  let totalCount = 0\n  let defaultHiddenCount = 0\n  let defaultHiddenTok = 0\n  let carrierHiddenCount = 0\n  let carrierHiddenTok = 0\n  for (const [key, tools] of buckets) {\n    if (!tools.length) continue\n    let tok = 0\n    let offTok = 0\n    for (const tool of tools) {\n      tok += tool.tok\n      totalCount += 1\n      if (tool.hidden) {\n        offTok += tool.tok\n        if (tool.defaultHidden) { defaultHiddenCount += 1; defaultHiddenTok += tool.tok }\n      } else if (carried.has(tool.name)) {\n        // 让位那一档：**不发，但不是被谁关掉的** —— 单独计，绝不并进 visible。\n        carrierHiddenCount += 1\n        carrierHiddenTok += tool.tok\n      } else { visibleTok += tool.tok; visibleCount += 1 }\n    }\n    hiddenTok += offTok\n    groups.push({ key, tools, tok, hiddenTok: offTok })\n  }\n  return {\n    groups, visibleTok, hiddenTok, totalTok: visibleTok + hiddenTok + carrierHiddenTok,\n    visibleCount, hiddenCount: totalCount - visibleCount - carrierHiddenCount, totalCount,\n    defaultHiddenCount, defaultHiddenTok, carrierHiddenCount, carrierHiddenTok,\n  }\n}\n"
    },
    {
      "path": "src/tools/control.ts",
      "content": "// 控制面工具 `tool_manager_tools`：模型自己看得到哪些工具、能不能自己打开。\n//\n// 为什么要有它：插件出厂只发 6 条工具（`src/tools/table.ts` 的 `DEFAULT_HIDDEN_TOOLS`\n// 关掉 18 条）。场景那一族**四条全关**，而场景目录注入只列**当前已启用的**场景 ——\n// 一个都没启用时整段不注入（`src/memories/constants.ts` 的 `SCENE_CATALOG_MAX_BYTES` 注释）。\n// 于是「用户说进入编程场景」这件事，模型既不知道有哪些场景，也没有开关工具：\n// 零信息 + 零手段，是死局。\n//\n// 这条工具把那个死局解开：**按需**查（列清单）、**按需**开（只对本对话）。\n// 它是唯一必须常驻的一条（其余能力一律按需调用，不进每轮的 schema）。\n//\n// 边界（有意不做的事）：\n//   · 只写**管着这个对话的那一层**：按会话 = 这个对话；按工作区 = 这个工作区（那一层本来就\n//     是同工作区共享的）；隔离关掉（全局）时没有会话层，管着这个对话的就是全局那一份 ——\n//     那一档是机器级改动，调用前会被确认卡问过。\n//   · 只认本插件注册过的工具名：MCP 工具归 MCP 停用表管，混进来会写出官方 restrict 认不出的名字。\n//   · 自己不可被关：唯一的回头路不能被自己关掉（面板仍然可以关）。\n\nimport { text, type ToolDomainDeps } from './deps.js'\nimport { governingScopeNote } from './deps.js'\nimport { applyToolTableToggles, estimateTok } from './table.js'\n\n/** 控制面工具要的依赖：本插件的工具清单 + 会话工具表的读写。 */\nexport interface ControlToolDeps extends ToolDomainDeps {\n  /** 本插件注册过的工具（名字 → 定义体积，字节）。 */\n  toolTableSizes: Map<string, number>\n  /** 工具名 → 一句话用途（描述首句）。 */\n  toolTableSummaries: Map<string, string>\n  /**\n   * 本对话当前生效的关停名单（会话层与全局并完的值）。\n   *\n   * 返回的是**并完**的那份：会话没有自己的名单时就是全局那份 —— 面板上看到的\n   * 「这个对话看得见几条」与模型看到的必须是同一份。\n   */\n  hiddenForSession(agent: unknown): ReadonlySet<string>\n  /**\n   * 逐条改管着这个对话的那一层的工具表。\n   *\n   * 走面板同一条写路径（`tool-table` op 的 `toggle` 那一支），所以锁、基线补写、\n   * 可见性重排、两个目录重算全都照旧 —— 这里不另写一份。带 sessionId 时写会话那一层，\n   * 不带时写全局那一份（隔离关掉时没有会话层，管着这个对话的就是全局那份；那一档是\n   * 机器级改动，调用前已被确认卡问过）。\n   *\n   * **逐条改**而不是整份替换：整份替换要先读出当前名单再算差量，读与写之间有窗口，\n   * 两个写者（面板、模型）会互相覆盖。逐条改在写锁里现读现改（见 `applyToolTableToggles`）。\n   */\n  applyToolTable(agent: unknown, changes: Array<{ name: string; hidden: boolean }>): Promise<{ ok: boolean; error?: string }>\n  /**\n   * 修复类动作：把**已损坏**的侧车改名留存、按空表继续。\n   *\n   * 这三个 op 在登记表里刻意**不冻结**（恢复路径不能被场景锁挡在门外），但模型此前\n   * 根本没有入口 —— 侧车一坏，模型手里的写操作全被拒，而它一个出口都没有。\n   * 破坏性（原始文件被改名留存），所以走确认卡（判据在 `src/confirm-gate.ts`）。\n   */\n  repair(kind: 'memory-index' | 'scope' | 'mcp-disabled'): Promise<{ ok: boolean; error?: string; message?: string }>\n}\n\n/** 一行清单：名字 · 用途 · ≈token。 */\nfunction toolLine(name: string, summary: string, bytes: number): string {\n  const purpose = summary === '' ? '' : ' — ' + summary\n  return '- ' + name + purpose + ' (≈' + estimateTok(bytes) + ' tok/turn)'\n}\n\n/** 这条工具自己的名字（自己不可被关的那条判据用）。 */\nconst CONTROL_TOOL_NAME = 'tool_manager_tools'\n\n/**\n * 注册控制面工具（`tool_manager_tools`）。\n *\n * 只做三件事：列清单、开工具、关工具。**没有第四件** ——\n * 「打开之后立刻用那条工具」的动作没有做：它要么绕过宿主的工具执行管线\n * （审批、输出校验都在那条管线上），要么依赖宿主「每个模型请求重新解析一次工具集」\n * 这个尚未核实的时序。前者不安全，后者大概率不需要（工具表是**作用域级**的限制，\n * 放开之后下一次请求组 schema 时就带上了）。\n */\nexport function buildControlTools(deps: ControlToolDeps): void {\n  const { defineTool, register } = deps\n  try {\n    register(defineTool({\n      name: CONTROL_TOOL_NAME,\n      description:\n        'Turn this plugin\\'s own tools on or off for the scope that governs this conversation '\n        + '(this conversation, its whole workspace under workspace isolation, or every conversation once isolation is off). '\n        + 'Call `list` when the user asks for something this conversation cannot do yet (e.g. switching scene while the scene tools are off): it returns the tools that are off here, one line each. '\n        + '`enable`/`disable` take one or more names and apply from the next request.',\n      parameters: {\n        action: {\n          type: 'string',\n          required: true,\n          enum: ['list', 'enable', 'disable', 'repair'],\n          description: 'list = tools off here; enable / disable = turn them on / off here; repair = fix a broken sidecar.',\n        },\n        tools: {\n          type: 'array',\n          items: { type: 'string' },\n          description: 'Names from `list`.',\n        },\n        target: {\n          type: 'string',\n          enum: ['memory-index', 'scope', 'mcp-disabled'],\n          description: 'For repair: memory-index | scope | mcp-disabled.',\n        },\n      },\n      output: { schema: { type: 'string' }, render: (_a: unknown, v: unknown) => text(String(v)) },\n      async execute(args: any, exec: any) {\n        const action = String((args && args.action) || '').trim()\n        const agent = exec && (exec as { agent?: unknown }).agent\n        if (action === 'list') return listTools(deps, agent)\n        if (action === 'repair') return repairState(deps, args)\n        if (action !== 'enable' && action !== 'disable') {\n          throw new Error('unknown action: ' + (action === '' ? '(missing)' : action) + ' — use list, enable, disable or repair')\n        }\n        const requested: string[] = (Array.isArray(args && args.tools) ? args.tools : [])\n          .map((n: unknown) => String(n ?? '').trim())\n          .filter((n: string) => n !== '')\n        if (requested.length === 0) throw new Error('missing argument: tools — the names of the tools to ' + action)\n        // 只认本插件注册过的名字：陌生名字写进关停名单会让官方的 restrict 抛错。\n        const known = requested.filter((n: string) => deps.toolTableSizes.has(n))\n        const unknown = requested.filter((n: string) => !deps.toolTableSizes.has(n))\n        if (known.length === 0) {\n          throw new Error('none of these are this plugin\\'s tools: ' + requested.join(', ') +\n            ' — call list to see the names')\n        }\n        // 自己不可被关：这条工具是模型唯一的回头路，关掉它就再也开不回来\n        // （面板仍然可以关 —— 用户说了算）。\n        if (action === 'disable' && known.includes(CONTROL_TOOL_NAME)) {\n          throw new Error('this tool cannot switch itself off — it is the only way back to the others. Only the user can disable it (in the panel).')\n        }\n        const hidden = deps.hiddenForSession(agent)\n        // 逐条改：每一处改动是一个「关掉 / 打开某一条」，写侧在锁里现读现改。\n        const changes = known.map((name) => ({ name, hidden: action === 'disable' }))\n        const next = applyToolTableToggles([...hidden], changes)\n        const saved = await deps.applyToolTable(agent, changes)\n        if (!saved.ok) throw new Error(saved.error || 'failed to save the tool table for this conversation')\n        const changed = changes.filter((c) => (c.hidden ? !hidden.has(c.name) : hidden.has(c.name))).map((c) => c.name)\n        const lines = [\n          'OK: ' + (action === 'enable' ? 'enabled' : 'disabled') + ': ' + (changed.join(', ') || '(nothing changed)')\n            + governingScopeNote(deps) + '.',\n          'These take effect from the next request.',\n        ]\n        if (unknown.length > 0) lines.push('not this plugin\\'s tools (ignored): ' + unknown.join(', '))\n        // 说清「这一层看得见的条数」：模型据此判断自己还有没有别的路。\n        const total = deps.toolTableSizes.size\n        lines.push((total - next.length) + ' of ' + total + ' tools are available here now.')\n        return lines.join('\\n')\n      },\n    }))\n  } catch (e) {\n    console.error('[dsh-plugin-tool-management] control tool registration failed:', deps.message(e))\n  }\n}\n\n/**\n * 修复动作：把已损坏的侧车改名留存、按空表继续。\n *\n * 回执要把「修好了什么」和「原来的数据去哪了」都写出来：被隔离的文件还在（改名留存），\n * 但插件从此不再读它 —— 模型说「已修复」时，用户得知道代价是什么。\n */\nasync function repairState(deps: ControlToolDeps, args: any): Promise<string> {\n  const target = String((args && args.target) || '').trim()\n  if (target !== 'memory-index' && target !== 'scope' && target !== 'mcp-disabled') {\n    throw new Error('missing argument: target — memory-index, scope or mcp-disabled')\n  }\n  const r = await deps.repair(target)\n  if (!r || r.ok === false) throw new Error((r && r.error) || 'repair failed')\n  const lines = ['OK: repaired ' + target + '.']\n  if (r.message) lines.push(String(r.message))\n  lines.push('The damaged file was renamed aside, not deleted; the plugin now continues with an empty table, so whatever it held no longer applies.')\n  return lines.join('\\n')\n}\n\n/**\n * 列出本对话现在**关着**的工具（能打开的那些）。\n *\n * 只列关着的：看得见的那些模型手里已经有 schema了，重复列一遍只是浪费上下文。\n */\nfunction listTools(deps: ControlToolDeps, agent: unknown): string {\n  const hidden = deps.hiddenForSession(agent)\n  const rows: string[] = []\n  for (const [name, bytes] of deps.toolTableSizes) {\n    if (!hidden.has(name)) continue\n    rows.push(toolLine(name, deps.toolTableSummaries.get(name) ?? '', bytes))\n  }\n  const total = deps.toolTableSizes.size\n  if (rows.length === 0) {\n    return 'every tool of this plugin is already on here (' + total + ' tools); nothing to enable.'\n  }\n  return 'tools switched off here (' + rows.length + ' of ' + total + '):\\n' +\n    rows.join('\\n') +\n    '\\ncall this tool with action=\"enable\" and the names you need (one or more).'\n}\n"
    },
    {
      "path": "src/scope/resolve.ts",
      "content": "// 会话身份解析：从 agent 反查 sessionId / cwd / 项目根 —— 全部\"取不到就返回 null\"。\n//\n// 为什么单独一个文件：三个域（注入、HTTP ops、模型工具）都要回答\"这是哪个会话\"，而\n// 取法只有一份。抄进各处就会分叉，分叉的症状是\"某一域按会话隔离生效、另一域不生效\"。\n//\n// ## 取不到 = 按全局（风险表最后一条）\n//\n// 冷恢复出来的临时 agent、宿主契约变更 —— 这些情况 sessionId 拿不到。这时**一律按全局\n// 处理**，不报错、不猜：猜错的代价是\"A 的设置漏进 B\"，而按全局最多是\"这一处没隔离\"，\n// 用户看得见、也不串内容。\n//\n// 子代理 / 侧聊**有**自己的 session id，但它属于父会话这个\"对话\"：作用域一律向上找到\n// 用户会话再查（`sessionScopeIdOf`），否则父会话里藏起来的服务器 / 技能 / 工具表，派一个\n// 子代理就能重新看见。\n//\n// ## 为什么不用 workspaceId\n//\n// 会话头里没有它。要拿得走 `ctx.workspaceRegistry` 线性查一遍（每个 step 一次）。\n// 「工作区隔离」因此以**会话头的 cwd** 为准（与下拉分组、工作区挂回同一口径），\n// 派生出的作用域键见 `scope/workspace-key.ts`；仍然不需要 workspaceId。\n\nimport { isWorkspaceScopeKey, workspaceScopeKeyOf } from './workspace-key.js'\nimport type { ScopeMode } from './scope-overrides.js'\n\n/** 一个 agent 的会话身份（任何一项取不到就是 null / undefined）。 */\nexport interface SessionIdentity {\n  sessionId: string\n  /** 会话的工作目录（宿主的 `header.cwd`）；没设过就是 undefined。 */\n  cwd?: string\n}\n\n/**\n * 见过的会话 cwd（工作区模式用）。\n *\n * 为什么另记一份：工作区作用域键要从**根会话**的 cwd 派生，而 `sessionScopeIdOf` 只沿着\n * `header.parentSession` 走 id，手里没有父会话的 header。父会话的 agent 先被看见时把 cwd\n * 记下来，子代理随后解析作用域就能拿到同一个工作区。上限与父链一致，满了丢最早的\n * （丢了最多退回会话隔离，不会串到别的工作区）。\n */\nconst SESSION_CWDS = new Map<string, string>()\nconst SESSION_CWDS_MAX = 4096\n\n/** 记下某个会话的 cwd（宿主清单 / 注入侧看到时顺手调；空值忽略）。 */\nexport function rememberSessionCwd(sessionId: string, cwd: unknown): void {\n  if (sessionId === '' || typeof cwd !== 'string' || cwd.trim() === '') return\n  SESSION_CWDS.set(sessionId, cwd.trim())\n  if (SESSION_CWDS.size > SESSION_CWDS_MAX) {\n    const oldest = SESSION_CWDS.keys().next()\n    if (!oldest.done) SESSION_CWDS.delete(oldest.value)\n  }\n}\n\n/** 某个会话的 cwd（只在见过的会话上有效；没记过 = undefined）。 */\nexport function sessionCwdOfId(sessionId: string): string | undefined {\n  return SESSION_CWDS.get(sessionId)\n}\n\n/**\n * 从 agent 取会话身份。取不到返回 null。\n *\n * 两条来源都认（与 `skills/service.ts` 的 `notifyChatCatalog` 同口径）：\n * `session.id` 与 `session.header.id`。前者是活会话对象上的直接字段，后者是持久化头；\n * 不同宿主路径给的是不同的那一个，只认一条会在某条路径上恒为 null。\n */\nexport function sessionIdentityOf(agent: unknown): SessionIdentity | null {\n  const session = (agent as { session?: unknown } | null | undefined)?.session\n  if (!session || typeof session !== 'object') return null\n  const bag = session as { id?: unknown; header?: { id?: unknown; cwd?: unknown } }\n  const rawId = typeof bag.id === 'string' && bag.id !== '' ? bag.id : bag.header?.id\n  if (typeof rawId !== 'string' || rawId === '') return null\n  const cwd = typeof bag.header?.cwd === 'string' && bag.header.cwd !== '' ? bag.header.cwd : undefined\n  if (cwd !== undefined) rememberSessionCwd(rawId, cwd)\n  return { sessionId: rawId, ...(cwd === undefined ? {} : { cwd }) }\n}\n\n/** 会话 id（取不到返回 null）。 */\nexport function sessionIdOf(agent: unknown): string | null {\n  return sessionIdentityOf(agent)?.sessionId ?? null\n}\n\n/**\n * 子会话 → 父会话（官方在会话头 `header.parentSession` 里记）。\n *\n * 只记内存：它是**活 agent 对象**上的一手信息，恢复出来的子会话重建 agent 时会再记一次。\n * 上限 4096 条，超了丢最早的 —— 键只是会话 id 字符串，丢了最多让深处嵌套的子代理退回\n * \"按全局\"，不会残留错误映射。\n */\nconst SESSION_PARENTS = new Map<string, string>()\nconst SESSION_PARENTS_MAX = 4096\n\n/** 一个 agent 的会话头里有没有 `parentSession`（子代理 / 侧聊派生）。 */\nfunction parentOfSession(agent: unknown): string | null {\n  try {\n    const session = (agent as { session?: unknown } | null | undefined)?.session\n    if (!session || typeof session !== 'object') return null\n    const parent = (session as { header?: { parentSession?: unknown } }).header?.parentSession\n    return typeof parent === 'string' && parent !== '' && parent !== '__proto__' ? parent : null\n  } catch { return null }\n}\n\n/**\n * 用于**作用域解析**的会话 id：子代理 / 侧聊会话 → 它所属的用户会话。\n *\n * 为什么必须往上找：作用域是按\"对话\"记的，而子代理有**自己的** session id。直接用子会话\n * id 查侧车必然查不到，于是它在全局口径下拿到父会话已经关掉的服务器 / 技能 / 工具表 ——\n * 父会话里藏起来的东西，派一个子代理就能看见。子代理属于同一个对话，作用域跟着父会话走。\n *\n * 解析链靠活 agent 的会话头逐层登记；某一环没登记过就停在那一层（宁可少隔离，不串到\n * 别的会话）。取不到 id 时返回 null，与 `sessionIdOf` 同口径。\n */\nexport function sessionScopeIdOf(agent: unknown): string | null {\n  const id = sessionIdOf(agent)\n  if (id === null) return null\n  const parent = parentOfSession(agent)\n  if (parent !== null && parent !== id) {\n    SESSION_PARENTS.set(id, parent)\n    if (SESSION_PARENTS.size > SESSION_PARENTS_MAX) {\n      const oldest = SESSION_PARENTS.keys().next()\n      if (!oldest.done) SESSION_PARENTS.delete(oldest.value)\n    }\n  }\n  let current = id\n  const seen = new Set<string>()\n  for (;;) {\n    const up = SESSION_PARENTS.get(current)\n    if (up === undefined || up === current || seen.has(up)) return current\n    seen.add(current)\n    current = up\n  }\n}\n\n// ── 工作区模式：把一个会话折叠到工作区作用域键 ──────────────────────\n\n/**\n * 一个**已知 cwd 的会话 id** → 当前模式下的作用域键（同步）。\n *\n *   · `global`    → `''`（没有会话层：调用方查不到任何记录，读侧自然落到各域全局）；\n *   · `session`   → 原样返回会话 id；\n *   · `workspace` → 有 cwd 且长度合法时返回 `ws:<归一化 cwd>`；否则原样返回会话 id。\n *\n * 已是工作区键的输入原样返回（面板选中的就是它）。冷会话 / 没见过 cwd 时退回会话隔离\n * ——宁可少共享一层，也不能猜到一个别的工作区上去。\n *\n * 空串是\"没有键\"的唯一表示，且它天然写不进去（`validRecordKey('')` 为 false）—— 所以\n * `global` 模式下任何试图写会话层的路径都会在 store 那一层被拒，不需要每个写入点自己记事。\n */\nexport function scopeKeyOfIdSync(sessionId: string, mode: ScopeMode): string {\n  if (mode === 'global') return ''\n  if (sessionId === '' || mode !== 'workspace' || isWorkspaceScopeKey(sessionId)) return sessionId\n  const cwd = sessionCwdOfId(sessionId)\n  return workspaceScopeKeyOf(cwd) ?? sessionId\n}\n\n/**\n * 从 agent 取**作用域键**（注入 / 守卫 / 目录 / 工具表用）。\n *\n * 粒度是\"对话\"：子代理 / 侧聊先向上找到所属用户会话；工作区模式下再用**根会话的 cwd**\n * 折叠到工作区。根会话 cwd 没见过时退回子会话自己的 cwd，再没有就退回会话 id\n * （与 `sessionScopeIdOf` 同一条\"宁可少隔离，不串到别处\"的取向）。\n *\n * `global` 模式返回 `null` = 这一处没有会话层。所有调用方已有的 `null → 按全局` 分支\n * 直接成立，不需要各自再判一次模式。注意仍然先走一遍 `sessionIdentityOf`：它顺手记下\n * 会话 cwd，切回工作区粒度时不必再等一次会话清单。\n */\nexport function scopeKeyOfAgent(agent: unknown, mode: ScopeMode): string | null {\n  const identity = sessionIdentityOf(agent)\n  if (identity === null) return null\n  if (mode === 'global') return null\n  const root = sessionScopeIdOf(agent)\n  if (root === null) return null\n  if (mode !== 'workspace') return root\n  const cwd = sessionCwdOfId(root) ?? identity.cwd\n  return workspaceScopeKeyOf(cwd) ?? root\n}\n"
    },
    {
      "path": "src/mcp/tool-visibility.ts",
      "content": "// 工具停用的那一层边界：停用表（TTL 缓存）、「已知工具」侧车、以及把停用名单装到每个\n// agent scope 上的可见性半边（restrict）+ 执行侧要用的开关写入口。\n//\n// 正文从 mcp/manager.ts 的 createMcpManager 闭包里整段搬来，一字未改（缩进本来就同层；\n// 改的只有闭包作用域的名字走 deps —— moved-verify 按这两类容差机检）：\n// ensurePaths / readJsonFile / writeJsonFile / withWriteLock / message / tools /\n// normalizeKnownTools，以及侧车的三件常量 SIDECAR_TTL_MS / MCP_DISABLED_TOOLS_FILE /\n// MCP_KNOWN_TOOLS_FILE 与落点函数 mcpSidecar。常量按**原名**传进来，是为了让搬来的那些行\n// 不必改名 —— 这一段读起来像「读一次侧车、 TTL 内不再读盘」，靠的就是那几个熟悉的名字。\n// deps 形参仍叫 deps：块里那五处 `deps.carrierHiddenTools` / `deps.pluginHiddenTools` 是\n// 原样文本，换名就要改行。\n//\n// 为什么这一簇必须整体搬：七个可见性状态量（disabledToolsCache / knownMcpToolsCache /\n// restrictTimer / appliedNamesKey / desiredNames / agentRestrictions / appliedByAgent /\n// seenAgents / epoch）里，只有 disabledToolsCache 被块外的 ops 段直接改写（改名、删台、\n// 整表回写三处 + 出口读两处），所以它由本模块交回两个句柄：setDisabledToolsCache（按原\n// 语义刷新 `{at, value}` 那份缓存）与 disabledToolsSnapshot（同步读，无 I/O —— 工具门禁在\n// 热路径上）。其余名字块外零引用，跟着走就行。\nimport { copyFile, stat } from 'node:fs/promises'\nimport { MCP_TOOL_PREFIX } from '../host-names.js'\nimport { clearRuntimeNote, noteRuntime } from '../compat/runtime-notes.js'\nimport {\n  classifyDisabledTools,\n  cloneDisabledTools,\n  DisabledToolsUnavailableError,\n  emptyDisabledTools,\n  isUnsafeKey,\n  type DisabledToolsIssue,\n  type DisabledToolsRead,\n  type JsonFileRead,\n} from './disabled-tools.js'\nimport type { KnownMcpTool, ToolsService } from './manager.js'\n\n/** 可见性接缝要的文件读写与路径解析。 */\nexport interface ToolVisibilityDeps {\n  /** 通用侧车 JSON 读写（与母文件同一套）。 */\n  readJsonFile(abs: string): Promise<any>\n  /** 严格读（区分 ENOENT / 解析失败 / IO 失败；不调 ensurePaths）。 */\n  readJsonFileStrict(abs: string): Promise<JsonFileRead>\n  writeJsonFile(abs: string, data: any): Promise<void>\n  /** 确保 hub 目录存在（每次读侧车前都调，与原实现一致）。 */\n  ensurePaths(): Promise<any>\n  /** 全局写锁：停用表的写都在它下面串行（同一异步调用链可重入）。 */\n  withWriteLock<T>(fn: () => Promise<T>): Promise<T>\n  /** 错误 → 文案（与全仓同源）。 */\n  message(e: unknown): string\n  /** 宿主 tools 服务：读不受限的插件级 schema 视图，装层则在 agent scope 上。 */\n  tools: ToolsService\n  /** 「已知工具」侧车一行的归一化（母文件的纯函数）。 */\n  normalizeKnownTools(raw: unknown): KnownMcpTool[]\n  /** MCP 侧车绝对路径（都在 hub 内）。 */\n  mcpSidecar(name: string): string\n  SIDECAR_TTL_MS: number\n  MCP_DISABLED_TOOLS_FILE: string\n  MCP_KNOWN_TOOLS_FILE: string\n  /** 「模型工具表」关掉的本插件工具（同步快照）。 */\n  pluginHiddenTools?(): string[]\n  /**\n   * 本插件**注册过**的工具名判据：这个名字是不是我们自己的工具。\n   *\n   * 为什么要有这条：观测日志要区分「关掉的是自家工具」与「关掉的是别的东西」，\n   * 而后者在这套设计里不该出现 —— 工具表只管自家那批（宿主工具归宿主，插件不代管）。\n   * 判据必须是**注册事实**（母文件那份注册漏斗记下的全集），不能靠枚举工具名前缀：\n   * 前缀表会漏 —— 控制面工具 `tool_manager_tools` 就不在「域名 + `_manager_`」那套前缀里，\n   * 漏掉它等于把自家工具误报成外来的。\n   *\n   * 缺省（未给）时不判（视为「没有外来工具」）：成功侧那行日志不触发，不影响功能。\n   */\n  isPluginToolName?(name: string): boolean\n  /** 「有官方等价物在场就让位」那半边：按 agent 算的额外 hide 名单。 */\n  carrierHiddenTools?(agent: unknown): Promise<string[]>\n  /**\n   * 本会话的 MCP 可见性覆盖：在**此刻注册着的**工具全名上算出的两个名单。\n   *\n   * 全名要按\"此刻注册了什么\"（`tools.schemas()`）算，而那件事只有本模块顺手 —— 让调用方\n   * 去拼全名等于把\"哪些名字算数\"抄第二份。所以调用方的判据（四层并值）是按\n   * `(server, tool)` 出的，展开成注册全名的这一步留在 `restrictAgent`（见那里的调用）。\n   *\n   * 语义边界：会话层**不改连接**（`cordis.patch.yml` 是进程级的），只让工具在本会话里\n   * 看不见。`allow` 名单会把全局停用表关着的工具**从 deny 里减掉** —— 本会话看得见、\n   * 调得动，别的会话照旧。\n   */\n  sessionMcpOverlay?(agent: unknown): Promise<{ allow?: readonly string[]; deny?: readonly string[] }>\n  /** 本会话的模型工具表覆盖：与 MCP overlay 合进同一层 restrict。 */\n  sessionToolTableOverlay?(agent: unknown): { allow?: readonly string[]; deny?: readonly string[] } | Promise<{ allow?: readonly string[]; deny?: readonly string[] }>\n}\n\n/** 可见性接缝的对外面：停用表、状态与问题上报。 */\nexport interface ToolVisibility {\n  readDisabledTools(force?: boolean): Promise<Record<string, string[]>>\n  /** 四态读（需要区分 ok / missing / corrupt / unreadable 时用）。 */\n  readDisabledToolsResult(force?: boolean): Promise<DisabledToolsRead>\n  /** 同步安全状态：首次读完成前、corrupt / unreadable 都是 unknown。 */\n  disabledToolsState(): 'ok' | 'unknown'\n  /** 诊断状态：UI 用它区分损坏 / 不可读；正常与 missing 为 null。 */\n  disabledToolsIssue(): DisabledToolsIssue | null\n  /** 最近一次损坏取证副本的绝对路径（没有副本 / 不可读时为 null）。 */\n  disabledToolsForensicPath(): string | null\n  /**\n   * 强制为异常停用表留一份取证副本（复制失败即抛）。corrupt / unreadable 的覆盖型写入\n   * 必须先过这一关；同一份文件已经复制成功过时会复用同一路径。\n   */\n  ensureDisabledToolsForensics(): Promise<string>\n  /**\n   * 重置停用表：仅在 corrupt / unreadable 时可用。两者都必须先取证成功才覆盖；\n   * 写回空表（原子写）并清掉 unknown 状态与上报。必须在写锁内调用（本函数自己加锁）。\n   */\n  resetDisabledTools(): Promise<{ ok: true; forensics: string | null; issue: DisabledToolsIssue } | { ok: false; error: string }>\n  readKnownMcpTools(force?: boolean): Promise<Record<string, KnownMcpTool[]>>\n  writeKnownMcpTools(value: Record<string, KnownMcpTool[]>): Promise<void>\n  mutateKnownMcpTools(mutate: (known: Record<string, KnownMcpTool[]>) => boolean): Promise<void>\n  mergeLiveToolsInto(known: Record<string, KnownMcpTool[]>, live: Record<string, KnownMcpTool[]>): boolean\n  mcpmToolEnabled(args: any): Promise<any>\n  attachAgent(agent: unknown): void\n  detachAgent(agent: unknown): void\n  applyToolRestrictions(): Promise<void>\n  scheduleToolRestrictions(): void\n  /** 母文件的 ops 段直接改写停用表时的落缓存入口（等价于原来的 `disabledToolsCache = {at, value}`）。 */\n  setDisabledToolsCache(value: Record<string, string[]>): void\n  /** 停用表的同步快照（无 I/O；未预热过时与原来一样给空表）。 */\n  disabledToolsSnapshot(): Record<string, string[]>\n  /** 卸载清理：清重排定时器、把挂在每个 agent scope 上的限制都撤掉。 */\n  disposeVisibility(): void\n}\n\n/** 工具可见性门面：把逐工具启停同时落到「看不见」（restrict）与「调不到」（guard）两侧。 */\nexport function createToolVisibility(deps: ToolVisibilityDeps): ToolVisibility {\n  // ---------- per-tool enable/disable (execution + visibility boundary) ----------\n  // dsh-mcp-client 没有逐工具配置，但 DSH 的工具运行时留了两个官方接缝：\n  // `tools.restrict({ deny })` 把全局工具从每个作用域对模型可见的 schema 列表里摘掉，\n  // `tools.guard` 在工具主体运行前拒绝调用。于是停用的工具既看不见也调不到 ——\n  // 不必改补丁，也不必重启 DSH。\n  let disabledToolsCache: { at: number; read: DisabledToolsRead; value: Record<string, string[]> } | null = null\n  /** 写成功后自增：晚到的旧读不得覆盖新缓存（见 readDisabledToolsResult）。 */\n  let disabledToolsEpoch = 0\n  /** 同一时刻只有一个读在飞；force 也先等它，避免并发读把磁盘放大。 */\n  let disabledToolsInflight: Promise<DisabledToolsRead> | null = null\n  /**\n   * 损坏文件的取证副本（copyFile，**不 rename**：原文件留在原处，外部工具仍能检查）。\n   * `key` = 路径 + size + mtime：同一份坏文件只复制一次，TTL 到期重读不会堆出一串副本。\n   */\n  let forensicCopy: { key: string; path: string | null } | null = null\n\n  function freshDisabledToolsRead(at: number): DisabledToolsRead | null {\n    return disabledToolsCache && at - disabledToolsCache.at < deps.SIDECAR_TTL_MS\n      ? disabledToolsCache.read\n      : null\n  }\n\n  /** 对外安全状态：首次读完成前、corrupt / unreadable 都是 unknown。 */\n  function disabledToolsState(): 'ok' | 'unknown' {\n    const read = disabledToolsCache?.read\n    if (!read) return 'unknown'\n    return read.status === 'ok' || read.status === 'missing' ? 'ok' : 'unknown'\n  }\n\n  function disabledToolsIssue(): DisabledToolsIssue | null {\n    const status = disabledToolsCache?.read.status\n    return status === 'corrupt' || status === 'unreadable' ? status : null\n  }\n\n  function publishDisabledToolsNotes(read: DisabledToolsRead, forensics: string | null = null): void {\n    if (read.status === 'ok' || read.status === 'missing') {\n      clearRuntimeNote('mcp-disabled-tools')\n    } else {\n      const forensicNote = forensics ? `；已保留取证副本：${forensics}` : ''\n      noteRuntime({\n        id: 'mcp-disabled-tools',\n        label: 'MCP 停用表',\n        kind: 'read',\n        fallback: 'refuse-operation',\n        detail: read.status === 'corrupt'\n          ? `MCP 停用表损坏（${read.error}）：所有 mcp__* 工具已被拒绝调用；请在 MCP 页重置停用表${forensicNote}。`\n          : `MCP 停用表不可读（${read.error}）：所有 mcp__* 工具已被拒绝调用；请检查文件权限或重置停用表${forensicNote}。`,\n        detailKey: read.status === 'corrupt' ? 'mcp-disabled-tools.corrupt' : 'mcp-disabled-tools.unreadable',\n        params: { reason: read.error, ...(forensics ? { forensics } : {}) },\n      })\n    }\n    if (read.status === 'ok' && read.warnings.length) {\n      noteRuntime({\n        id: 'mcp-disabled-tools-names',\n        label: 'MCP 停用表中的工具名',\n        kind: 'read',\n        fallback: 'inform-only',\n        detail: '停用表里有本插件工具名格式不认识的名字，已原样保留并继续参与拦截：' + read.warnings.join('、'),\n        detailKey: 'mcp-disabled-tools.names',\n        params: { names: read.warnings.join('、') },\n      })\n    } else if (read.status !== 'corrupt' && read.status !== 'unreadable') {\n      clearRuntimeNote('mcp-disabled-tools-names')\n    }\n  }\n\n  async function readDisabledToolsOnce(): Promise<DisabledToolsRead> {\n    const result = await deps.readJsonFileStrict(deps.mcpSidecar(deps.MCP_DISABLED_TOOLS_FILE))\n    if (result.status !== 'ok') return result\n    return classifyDisabledTools(result.value)\n  }\n\n  async function readDisabledToolsResult(force = false): Promise<DisabledToolsRead> {\n    const startedAt = Date.now()\n    if (!force) {\n      const cached = freshDisabledToolsRead(startedAt)\n      if (cached) return cached\n    }\n    if (disabledToolsInflight) {\n      const shared = await disabledToolsInflight\n      if (!force) return shared\n      if (disabledToolsCache && disabledToolsCache.at >= startedAt) return disabledToolsCache.read\n    }\n    if (!force) {\n      const cached = freshDisabledToolsRead(startedAt)\n      if (cached) return cached\n    }\n    const startEpoch = disabledToolsEpoch\n    const task = (async () => {\n      const read = await readDisabledToolsOnce()\n      // 读期间有写完成：写侧已经把新值放进缓存并 bump 了 epoch，晚到的旧读不得覆盖它。\n      if (disabledToolsEpoch !== startEpoch && disabledToolsCache) return disabledToolsCache.read\n      // 损坏时自动留一份取证副本（同一份坏文件只留一次）。失败不改变 fail-closed 结论，\n      // 只是 note 里没有路径 —— 用户仍可从 MCP 页重置（重置路径会强制取证）。\n      let forensics: string | null = null\n      if (read.status === 'corrupt') {\n        try { forensics = await copyCorruptDisabledTools(false) } catch { forensics = null }\n      }\n      const value = read.status === 'ok' ? read.value : emptyDisabledTools()\n      disabledToolsCache = { at: Date.now(), read, value }\n      publishDisabledToolsNotes(read, forensics)\n      return read\n    })()\n    disabledToolsInflight = task\n    try {\n      return await task\n    } finally {\n      if (disabledToolsInflight === task) disabledToolsInflight = null\n    }\n  }\n\n  /**\n   * 兼容出口：ok / missing 返回表，corrupt / unreadable 抛具名错误。\n   *\n   * 新代码应优先用 `readDisabledToolsResult`（需要区分状态时）或 `disabledToolsState`\n   * （同步判定）。保留这个出口是为了让“没接状态的消费者”至少 fail-closed，而不是读到空表。\n   */\n  async function readDisabledTools(force = false): Promise<Record<string, string[]>> {\n    const read = await readDisabledToolsResult(force)\n    if (read.status === 'ok') return read.value\n    if (read.status === 'missing') return emptyDisabledTools()\n    throw new DisabledToolsUnavailableError(read.status, read.error)\n  }\n\n  /** 同一份坏文件的稳定标识：路径 + 大小 + mtime（读不到元数据时退化为路径）。 */\n  async function forensicKeyOf(abs: string): Promise<string> {\n    try {\n      const st = await stat(abs)\n      return abs + ':' + st.size + ':' + st.mtimeMs\n    } catch {\n      return abs\n    }\n  }\n\n  /**\n   * 把损坏的停用表复制一份到 `<侧车>.corrupt-<ts>`（**不 rename**，原文件留在原处）。\n   *\n   * `requireSuccess`：重置路径下取证是**前置条件** —— 复制不了就不许覆盖，否则证据没了\n   * 还把一个无法解释的状态洗白。读路径下的自动取证失败不算错误（fail-closed 照旧），\n   * 只是没有副本可给用户。\n   */\n  async function copyCorruptDisabledTools(requireSuccess: boolean): Promise<string | null> {\n    const abs = deps.mcpSidecar(deps.MCP_DISABLED_TOOLS_FILE)\n    const key = await forensicKeyOf(abs)\n    if (forensicCopy && forensicCopy.key === key && (forensicCopy.path !== null || !requireSuccess)) {\n      return forensicCopy.path\n    }\n    const dest = abs + '.corrupt-' + new Date().toISOString().replace(/[:.]/g, '-')\n    try {\n      await copyFile(abs, dest)\n      forensicCopy = { key, path: dest }\n      return dest\n    } catch (e) {\n      forensicCopy = { key, path: null }\n      if (requireSuccess) throw new Error('取证副本写入失败（未改动原文件）：' + deps.message(e))\n      return null\n    }\n  }\n\n  /** 覆盖型写入的前置条件：异常状态必须先留下一份可检查的原文件副本。 */\n  async function ensureDisabledToolsForensics(): Promise<string> {\n    const path = await copyCorruptDisabledTools(true)\n    if (path === null) throw new Error('取证副本写入失败（未改动原文件）')\n    return path\n  }\n\n  /** 写成功后的唯一缓存入口：安全克隆 + bump epoch + 清掉损坏上报。 */\n  function setDisabledToolsCacheInternal(value: Record<string, string[]>): void {\n    disabledToolsEpoch += 1\n    const safe = cloneDisabledTools(value)\n    disabledToolsCache = { at: Date.now(), read: { status: 'ok', value: safe, warnings: [] }, value: safe }\n    clearRuntimeNote('mcp-disabled-tools')\n    clearRuntimeNote('mcp-disabled-tools-names')\n  }\n\n  /**\n   * 重置停用表（仅 unknown 时可用）。\n   *\n   * 顺序不可换：先**证明**状态确实异常 → 损坏时先取证（复制不了就中止，绝不在\n   * \"证据保不住\"的情况下覆盖）→ 原子写空表 → 清缓存 / note → 重排可见性。\n   * 正常可读的表拒绝重置：这个入口是恢复通道，不是\"清空我的配置\"的捷径。\n   */\n  async function resetDisabledTools(): Promise<{ ok: true; forensics: string | null; issue: DisabledToolsIssue } | { ok: false; error: string }> {\n    return deps.withWriteLock(async () => {\n      let read: DisabledToolsRead\n      try {\n        read = await readDisabledToolsResult(true)\n      } catch (e) {\n        return { ok: false as const, error: '读取停用表失败：' + deps.message(e) }\n      }\n      if (read.status === 'ok' || read.status === 'missing') {\n        return { ok: false as const, error: '停用表当前可读（未损坏 / 未不可读），重置入口只在状态异常时可用；未改动任何东西' }\n      }\n      let forensics: string | null = null\n      // corrupt 与 unreadable 都是异常状态：覆盖之前必须证明证据保得住。unreadable 时\n      // copyFile 往往也会失败 —— 那就如实拒绝（先修权限 / 释放占用），绝不空表覆盖。\n      try {\n        forensics = await ensureDisabledToolsForensics()\n      } catch (e) {\n        return { ok: false as const, error: deps.message(e) }\n      }\n      try {\n        await deps.writeJsonFile(deps.mcpSidecar(deps.MCP_DISABLED_TOOLS_FILE), {})\n      } catch (e) {\n        return { ok: false as const, error: '重置停用表失败（未改动原有内容）：' + deps.message(e) }\n      }\n      setDisabledToolsCacheInternal(emptyDisabledTools())\n      scheduleToolRestrictions()\n      return { ok: true as const, forensics, issue: read.status }\n    })\n  }\n\n  /** 每个停用工具对模型的全名（`mcp__<serverName>__<tool>`）。 */\n  function disabledToolNames(map: Record<string, string[]>): string[] {\n    const out: string[] = []\n    for (const serverName of Object.keys(map)) {\n      for (const tool of map[serverName]) out.push(MCP_TOOL_PREFIX + serverName + '__' + tool)\n    }\n    return out\n  }\n  // ---------- 「已知工具」侧车 -------------------------------------------\n  // MCP 工具名只在服务器**运行**时可见（tools.schemas() 里才有）。未运行的服务器在\n  // 场景档案里既显示 0 工具、工具明细也空空如也 —— 用户没法给未运行服务器挑工具。\n  // 每次枚举到 live 工具时按 serverName 记一份「最后见过的工具名」，未运行时用它兜底：\n  // 场景档案能列出/勾选，进入场景后按实际注册的工具生效（restrict 会过滤掉不存在的名字）。\n  let knownMcpToolsCache: { at: number; value: Record<string, KnownMcpTool[]> } | null = null\n  async function readKnownMcpTools(force = false): Promise<Record<string, KnownMcpTool[]>> {\n    if (knownMcpToolsCache && !force && Date.now() - knownMcpToolsCache.at < deps.SIDECAR_TTL_MS) return knownMcpToolsCache.value\n    // 读路径不调 ensurePaths：hubPath 走 resolveDshHome，与补丁路径推导无关（见 G1）。\n    const raw = await deps.readJsonFile(deps.mcpSidecar(deps.MCP_KNOWN_TOOLS_FILE))\n    const out = Object.create(null) as Record<string, KnownMcpTool[]>\n    if (raw && typeof raw === 'object') {\n      for (const [serverName, value] of Object.entries(raw as Record<string, unknown>)) {\n        if (isUnsafeKey(serverName)) continue\n        const list = deps.normalizeKnownTools(value)\n        if (list.length) out[serverName] = list\n      }\n    }\n    knownMcpToolsCache = { at: Date.now(), value: out }\n    return out\n  }\n  async function writeKnownMcpTools(value: Record<string, KnownMcpTool[]>): Promise<void> {\n    const p = await deps.ensurePaths()\n    await deps.writeJsonFile(deps.mcpSidecar(deps.MCP_KNOWN_TOOLS_FILE), value)\n    knownMcpToolsCache = { at: Date.now(), value: value }\n  }\n  /**\n   * 「已知工具」侧车的**读-改-写**，整段在写锁内。\n   *\n   * 为什么不能「先 readKnownMcpTools() 再 writeKnownMcpTools()」：\n   * 这个侧车有两个并发写者 —— 列表轮询（`mcpmListView`，每次发现新工具就回写）与\n   * 临时启动（`mcpmTools` 等到工具注册后回写）。两步之间是队外窗口，两个写者各读到同一份\n   * 旧表、各并进自己那一台服务器的工具，后写的把先写的整份覆盖掉 —— 先那台的\"曾经见过\"\n   * 记录消失，未运行时场景档案里又变成 0 工具。\n   *\n   * `mutate` 收到的是**锁内刚读出来**的表（`force` 绕 TTL，否则拿到的还是锁外那份缓存）；\n   * 返回 `true` 表示有变化、需要落盘。\n   * 注意：`withWriteLock` 在同一异步调用链上可重入（重入直接并入外层临界区、不再排队），\n   * 但重入不会重新读盘 —— 需要\"锁内刚写下的值\"时必须显式 `force`。\n   */\n  async function mutateKnownMcpTools(mutate: (known: Record<string, KnownMcpTool[]>) => boolean): Promise<void> {\n    return deps.withWriteLock(async () => {\n      const known = await readKnownMcpTools(true)\n      if (!mutate(known)) return\n      await writeKnownMcpTools(known)\n    })\n  }\n  /**\n   * 把「这次 live 见到的工具」并进一份已知工具表；返回是否有变化。\n   *\n   * **live 见到就整体替换那一台**（用户实测：dhole 升级把 `smart_fetch` 一族改名成\n   * `web_*` 之后，旧名字永远留在表里，详情页每轮都把死名字当「上次运行时」列出来，「刷新工具」\n   * 也刷不掉 —— 它早先只要缓存非空就直接返回，而轮询路径的合并又是只进不出的并集）。理由：\n   * 一台**正在运行**的服务器，它注册进来的工具集就是权威全貌，此刻已经不存在的旧名字留着，\n   * 只会让界面拿\"曾经见过\"冒充\"现在也有\"。这份缓存的存在意义是「服务器没跑时的兜底」，\n   * 不是历史博物馆。\n   *\n   * 只在 `live` 里**有这台并且非空**时才替换：这次没见到（服务器没跑 / 还没注册工具）就原样\n   * 保留上一份 —— 否则一台掉线的服务器会被清空，场景档案随即失去挑工具的候选。\n   * 描述按「live 优先、旧的兜底」合并：个别服务器会省略描述，别把上次记下来的那份弄丢。\n   *\n   * 抽出来是为了让\"要不要写盘\"的判断与\"锁内真正合并\"用**同一个**函数：调用方先在锁外\n   * 对本地缓存跑一遍拿到 `changed`（决定要不要进锁），进锁后再对新鲜表跑一遍（那次的结果\n   * 才决定落盘）—— 两边口径不一致的话，要么白写要么漏写。\n   */\n  function mergeLiveToolsInto(known: Record<string, KnownMcpTool[]>, live: Record<string, KnownMcpTool[]>): boolean {\n    let changed = false\n    for (const [server, list] of Object.entries(live)) {\n      if (!list.length) continue\n      const prev = known[server] || []\n      const prevByName = new Map(prev.map((t) => [t.name, t] as const))\n      const next = list.map((tool) => {\n        const old = prevByName.get(tool.name)\n        const description = tool.description || (old && old.description) || ''\n        return description ? { name: tool.name, description } : { name: tool.name }\n      }).sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))\n      const same = next.length === prev.length\n        && next.every((t, i) => t.name === prev[i].name && (t.description || '') === (prev[i].description || ''))\n      if (!same) changed = true\n      known[server] = next\n    }\n    return changed\n  }\n  async function mcpmToolEnabled(args: any): Promise<any> {\n    const serverName = String((args && args.serverName) || '').trim()\n    const tool = String((args && args.tool) || '').trim()\n    if (!/^[A-Za-z0-9_-]{1,32}$/.test(serverName)) return { ok: false, error: 'serverName 不合法' }\n    if (!/^[A-Za-z0-9_-]{1,128}$/.test(tool)) return { ok: false, error: 'tool 名称不合法' }\n    const enabled = (args && args.enabled) !== false\n    const p = await deps.ensurePaths()\n    return deps.withWriteLock(async () => {\n      // 强制重读：外部改过的停用表要被合并进来，不能被旧缓存覆盖掉。\n      const read = await readDisabledToolsResult(true)\n      if (read.status === 'corrupt' || read.status === 'unreadable') {\n        return {\n          ok: false,\n          code: 'mcp-disabled-unreadable',\n          error: `MCP 停用表${read.status === 'corrupt' ? '损坏' : '不可读'}，已拒绝写入：${read.error}`,\n        }\n      }\n      const map = cloneDisabledTools(read.status === 'ok' ? read.value : emptyDisabledTools())\n      const disabled = new Set(map[serverName] || [])\n      if (enabled) disabled.delete(tool)\n      else disabled.add(tool)\n      if (disabled.size) map[serverName] = [...disabled].sort()\n      else delete map[serverName]\n      try {\n        await deps.writeJsonFile(deps.mcpSidecar(deps.MCP_DISABLED_TOOLS_FILE), map)\n      } catch (e) {\n        return { ok: false, error: '保存失败: ' + deps.message(e) }\n      }\n      setDisabledToolsCacheInternal(map)\n      await applyToolRestrictions()\n      return { ok: true, serverName, disabled: map[serverName] || [] }\n    })\n  }\n\n  // 可见性接缝：**每个 agent 作用域**只保留一条生效的 restriction，工具集 / 停用集 /\n  // 该 agent 的载体集任一变化就刷新。三条官方源码事实决定了这个设计：\n  //   · `restrict()` **要求 scoped context** —— 插件级 ctx 调用必抛 \"requires a scoped\n  //     context\"—— 这正是「停用工具从模型可见 schema 消失」这半边一直没生效的原因；\n  //   · 每次 layer 变化（restriction 就是一次 layer effect）官方都会 emit `tools/change`\n  //     （`layers = new ScopedLayers(…, () => this.ctx.emit(\"tools/change\"))`），而重放正挂在\n  //     `tools/change` 上 —— 名单没变还重放就是自激；\n  //   · 表要取自**不受限**的插件级视图：在 agent scope 里取 `schemas()`，第一次限制生效后\n  //     表里就没有被停用的工具了，第二次重放会把它从 deny 名单里筛掉 —— 停用静默复活。\n  // （：名单有三处来源，其中 `carrierHiddenTools` 逐 agent 不同，所以从\"一份名单给\n  //  所有 agent\"改成逐 agent 各装一层 —— 见下面 restrictAgent / appliedByAgent 的注释。）\n  let restrictTimer: ReturnType<typeof setTimeout> | null = null\n  /** 已应用名单的键；相同即返回（防自激，也让每次 tools/change 变成一次廉价判等）。 */\n  let appliedNamesKey: string | null = null\n  /** 当前期望的**全局** deny 名单（agent 晚到 / 重放时用它，再叠加该 agent 自己那份）。 */\n  let desiredNames: string[] = []\n  /** agent → 撤掉这层限制的 disposer。 */\n  const agentRestrictions = new Map<unknown, () => void>()\n  /** agent → 已应用的**合并后**名单键（名单现在与 agent 有关，不能再只记一份全局的）。 */\n  const appliedByAgent = new Map<unknown, string>()\n  /** 见过的 agent（重放时逐个重新应用；disposed 时移除）。 */\n  const seenAgents = new Set<unknown>()\n  /**\n   * 已报过的装层失败：(agent, 名单, 原因) → 已报。\n   *\n   * 为什么要有：装层失败没有「键相同就跳过」的保护（没装上就得再试），\n   * 而 `tools/change` 空闲时也能到十几次/秒 —— 不去重的话同一份失败会刷满日志，\n   * 真正的新问题反而被淹没。名单或原因变了才算新问题，才会再报一行。\n   *\n   * 键里带 agent 身份：不同 scope 的失败是不同的事。\n   */\n  const reportedRestrictFailures = new Map<string, boolean>()\n  /** agent 的可读标识（给日志用；读不到就退化成空串，不影响判断）。 */\n  const agentIdOf = (agent: unknown): string => {\n    try {\n      const id = (agent as { id?: unknown })?.id\n      return id === undefined || id === null ? '' : String(id)\n    } catch { return '' }\n  }\n  /**\n   * 重放代数：`carrierHiddenTools` 是异步的，算名单期间可能又来了新的一轮重放（或 agent\n   * 已经下线）。每次重放自增，回来时代数对不上就作废 —— 否则会用旧名单盖掉新的那一层。\n   */\n  let epoch = 0\n\n  function scopedToolsOf(agent: any): { restrict?: (filter: { deny?: readonly string[] }) => unknown } | undefined {\n    const scoped = agent && agent.ctx && agent.ctx.tools\n    return scoped && typeof scoped === 'object' ? scoped : undefined\n  }\n\n  /** 撤掉某个 agent 上的限制（名单变了要重装：`restrict` 是叠加层，装新的不撤旧的会越叠越多）。 */\n  function liftRestriction(agent: any): void {\n    const release = agentRestrictions.get(agent)\n    agentRestrictions.delete(agent)\n    appliedByAgent.delete(agent)\n    if (release) { try { release() } catch (e) { /* ignore */ } }\n  }\n\n  /** 把该 agent 该背的名单装到它 scope 上（全局那份 ∓ 会话覆盖 ∪ 它自己那份；空名单 = 不碰它）。 */\n  async function restrictAgent(agent: any): Promise<void> {\n    const mine = epoch\n    let extra: string[] = []\n    if (deps.carrierHiddenTools) {\n      // 判据失败一律当\"没有额外要藏的\"：藏错了模型就少一条路，留着只是多花 token。\n      try { extra = await deps.carrierHiddenTools(agent) } catch (e) { extra = [] }\n    }\n    // 会话层的两个方向：`deny` 追加、`allow` 从全局名单里减掉 —— 允许**减**\n    // 是关键：全局停用表（含场景引擎写的收窄）关着的工具，本会话显式拨开 / 场景勾着时\n    // 要能重新看见，而全局一个字不动。名单已按注册全名算过（调用方用同一份 schemas），\n    // 这里照样过一遍 registered 过滤 —— 认不出的名字官方 restrict 会直接抛。\n    let allowSet = new Set<string>()\n    if (deps.sessionMcpOverlay) {\n      try {\n        const ov = await deps.sessionMcpOverlay(agent)\n        if (ov) {\n          if (ov.deny !== undefined && ov.deny.length) extra = [...extra, ...ov.deny]\n          if (ov.allow !== undefined && ov.allow.length) allowSet = new Set(ov.allow)\n        }\n      } catch { /* 取不到会话覆盖 = 按\"没有额外要藏的\"算（跟随全局） */ }\n    }\n    // 模型工具表也按对话走：本对话的整份名单可能重新打开全局关掉的工具\n    // 也可能关掉全局开着的工具 —— 与 MCP 覆盖同一层 deny，不各装一层。\n    if (deps.sessionToolTableOverlay) {\n      try {\n        const ov = await deps.sessionToolTableOverlay(agent)\n        if (ov) {\n          if (ov.deny !== undefined && ov.deny.length) extra = [...extra, ...ov.deny]\n          if (ov.allow !== undefined && ov.allow.length) for (const name of ov.allow) allowSet.add(name)\n        }\n      } catch { /* 取不到 = 跟随全局 */ }\n    }\n    if (mine !== epoch) return\n    if (!seenAgents.has(agent)) return\n    // unknown 时 desiredNames 已经包含全部 mcp__*；会话 allow 不得把它们减掉\n    // （本会话显式开着也不能越过“停用表读不出来”）。工具表的 allow 不受影响。\n    const effectiveAllow = disabledToolsState() === 'unknown'\n      ? new Set([...allowSet].filter((name) => !name.startsWith(MCP_TOOL_PREFIX)))\n      : allowSet\n    const names = [...new Set([...desiredNames.filter((name) => !effectiveAllow.has(name)), ...extra])]\n    const scoped = scopedToolsOf(agent)\n    if (!scoped || typeof scoped.restrict !== 'function') {\n      if (names.length === 0) return\n      // agent scope 上没有 tools 面（或它没有 restrict）：这半边做不成，如实说 ——\n      // 静默跳过会让人以为\"停用工具从模型工具表里消失\"已经生效。\n      noteRuntime({\n        id: 'mcp-tool-visibility',\n        label: '停用工具的可见性',\n        kind: 'write',\n        fallback: 'inform-only',\n        detail: 'agent scope 上没有可用的 tools.restrict（官方接口变了或该 scope 未暴露 tools）：停用的 MCP 工具与兼容页关掉的本插件工具仍会出现在模型可见的工具表里，执行侧拦截仍然生效。',\n        detailKey: 'mcp-tool-visibility.no-restrict',\n      })\n      return\n    }\n    // 从枚举到装层之间可能过去一拍：服务器恰好停了 / 注册被摘掉，而官方 `restrict` 对\n    // 认不出的名字是**整份名单抛错**（不是跳过那一个）—— 一个过期名字就会让所有工具重新\n    // 出现在模型工具表里。装之前再问一次全局视图，把已经不存在的名字剔掉。\n    const denyNames = typeof deps.tools.get === 'function'\n      ? names.filter((name) => { try { return deps.tools.get!(name) !== undefined } catch { return false } })\n      : names\n    const denyKey = denyNames.slice().sort().join('\\u0000')\n    if (appliedByAgent.get(agent) === denyKey) return\n    liftRestriction(agent)\n    if (denyNames.length === 0) { clearRuntimeNote('mcp-tool-visibility'); return }\n    try {\n      const dispose = scoped.restrict({ deny: denyNames })\n      agentRestrictions.set(agent, typeof dispose === 'function' ? dispose as () => void : () => {})\n      appliedByAgent.set(agent, denyKey)\n      clearRuntimeNote('mcp-tool-visibility')\n      // 成功路径此前完全静默，出问题时日志里看不到任何证据 —— 只能靠猜。\n      // 报这一行是为了让「工具表关掉了什么、这一层装上了没有」在命令行就能查。\n      //\n      // 只在**装上了非自家工具**时才打：工具表只管自家那批，deny 名单里出现别的东西\n      // 意味着